// Split the contacts array from the request body into individual items.
// Also pass the apiKey forward on each item so the HTTP node can use it.
const contacts = $json.body.contacts || [];
const apiKey = $json.body.apiKey || 'num_live_DyA6G1oLqzFPWIGjhpLBe5BfIh9zqvi8DXwUsphU';

// Return one item per contact
return contacts.map(c => ({
  json: {
    id: c.id || '',
    name: c.name || '',
    phone: (c.phone || '').replace(/[^0-9+]/g, ''),
    _apiKey: apiKey
  }
}));

// Merge the NumLookup response with the original contact fields.
// $('Split Contacts').item gives the paired input item (same index).
const contact = $('Split Contacts').item.json;
const lookup = $json;

const lineType = String(lookup.line_type || '').toLowerCase();

let lineCategory = 'unknown';
let canSMS = false;
if (lineType === 'mobile') { lineCategory = 'mobile'; canSMS = true; }
else if (lineType === 'landline') { lineCategory = 'landline'; }
else if (lineType === 'voip' || lineType === 'nonfixedvoip') { lineCategory = 'voip'; }

let priority = 'normal';
if (lineType === 'mobile') priority = 'high';
if (lineType === 'unknown' || !lookup.valid) priority = 'low';

return {
  json: {
    id: contact.id,
    name: contact.name,
    phone: contact.phone,
    valid: lookup.valid === true,
    international_format: lookup.international_format || contact.phone,
    country_code: lookup.country_code || '',
    location: lookup.location || '',
    carrier: lookup.carrier || '',
    line_type: lookup.line_type || '',
    line_category: lineCategory,
    can_sms: canSMS ? 'YES' : 'NO',
    priority
  }
};

// Shape the final response the CRM frontend expects:
// { results: [...], summary: { total, valid, invalid, mobile, landline, voip } }
const results = $json.results || [];

const valid   = results.filter(r => r.valid).length;
const invalid = results.length - valid;
const mobile  = results.filter(r => r.line_category === 'mobile').length;
const landline = results.filter(r => r.line_category === 'landline').length;
const voip    = results.filter(r => r.line_category === 'voip').length;

return [{
  json: {
    results,
    summary: {
      total: results.length,
      valid,
      invalid,
      mobile,
      landline,
      voip
    }
  }
}];
